package wallet

import (
	"errors"
	"strings"
	"testing"
	"time"
)

func TestRestoreApprovalDisabledNegativeWait(t *testing.T) {
	base := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	w := New()
	w.now = func() time.Time { return base }
	if err := w.AddAccount("payer", 100); err != nil {
		t.Fatal(err)
	}
	if err := w.AddAccount("user", 0); err != nil {
		t.Fatal(err)
	}
	sess, err := w.OpenSession("user", "dev1", base.Add(time.Hour))
	if err != nil {
