package wallet

import (
	"encoding/json"
	"errors"
	"strings"
	"testing"
	"time"
)

func decodeBackup(t *testing.T, data []byte) map[string]interface{} {
	t.Helper()
	var b map[string]interface{}
	if err := json.Unmarshal(data, &b); err != nil {
		t.Fatal(err)
	}
	return b
}

func encodeBackup(t *testing.T, b map[string]interface{}) []byte {
	t.Helper()
	data, err := json.Marshal(b)
	if err != nil {
		t.Fatal(err)
	}
	return data
}

func TestRestoreApprovalDisabledNegativeWait(t *testing.T) {
	base := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	w := New()
	w.now = func() time.Time { return base }
	if _, err := w.CreateAccount("payer", 100); err != nil {
		t.Fatal(err)
	}
	if _, err := w.CreateAccount("user", 0); err != nil {
		t.Fatal(err)
	}
	sess, err := w.CreateSession("s1", "user", "dev1", base.Add(time.Hour))
	if err != nil {
		t.Fatal(err)
	}
	spec := PolicySpec{
		ID:                 "pol",
		PayerAccountID:     "payer",
		AllowedAccountIDs:  []string{"user"},
		Operation:          "op",
		Payee:              "payee",
		StartsAt:           base.Add(-time.Hour),
		EndsAt:             base.Add(time.Hour),
		MaxPerRequest:      50,
		MaxTotal:           100,
		ApprovalThreshold:  0,
		ApprovalWait:       -time.Second, // 关闭审批时忽略，允许负值
		MaxReserveDuration: 30 * time.Minute,
	}
	if err := w.SavePolicy(spec); err != nil {
		t.Fatal(err)
	}
	// 合法申请直接预留 20。
	if _, err := w.Apply(RequestInput{
		PolicyID: "pol", RequestID: "r1", AccountID: "user", SessionID: sess.ID,
		DeviceID: "dev1", Operation: "op", Payee: "payee", EstimatedFee: 20,
	}); err != nil {
		t.Fatal(err)
	}

	backup, err := w.Export()
	if err != nil {
		t.Fatal(err)
	}
	// 预留未到期时恢复。
	w2, err := restoreAt(backup, base.Add(time.Minute))
	if err != nil {
		t.Fatalf("restore failed: %v", err)
	}
	// 策略查询必须返回原值 -1s，不得改为零或开启审批。
	pv, err := w2.Policy("pol")
	if err != nil {
		t.Fatal(err)
	}
	if pv.ApprovalWait != -time.Second || pv.ApprovalThreshold != 0 {
		t.Fatalf("policy not preserved: wait=%v threshold=%d", pv.ApprovalWait, pv.ApprovalThreshold)
	}
	// 余额：可用 80、预留 20。
	bal, err := w2.Balance("payer")
	if err != nil {
		t.Fatal(err)
	}
	if bal.Available != 80 || bal.Reserved != 20 {
		t.Fatalf("balances: %+v", bal)
	}
	// 原请求仍为已预留，无待审批记录。
	rv, err := w2.Request("user", "r1")
	if err != nil {
		t.Fatal(err)
	}
	if rv.State != RequestReserved {
		t.Fatalf("request state: %v", rv.State)
	}
	// 按实际费用 5 结算：可用 95、预留 0。
	if _, err := w2.Settle("user", "r1", 5); err != nil {
		t.Fatal(err)
	}
	bal, _ = w2.Balance("payer")
	if bal.Available != 95 || bal.Reserved != 0 {
		t.Fatalf("after settle: %+v", bal)
	}
	// 新合规申请仍直接预留，不转入待审批。
	if _, err := w2.Apply(RequestInput{
		PolicyID: "pol", RequestID: "r2", AccountID: "user", SessionID: sess.ID,
		DeviceID: "dev1", Operation: "op", Payee: "payee", EstimatedFee: 10,
	}); err != nil {
		t.Fatal(err)
	}
	rv2, _ := w2.Request("user", "r2")
	if rv2.State != RequestReserved || !rv2.WaitDeadline.IsZero() {
		t.Fatalf("new request: state=%v waitDeadline=%v", rv2.State, rv2.WaitDeadline)
	}
	// 再次导出→恢复仍保留原配置。
	backup2, err := w2.Export()
	if err != nil {
		t.Fatal(err)
	}
	w3, err := restoreAt(backup2, base.Add(2*time.Minute))
	if err != nil {
		t.Fatal(err)
	}
	pv3, _ := w3.Policy("pol")
	if pv3.ApprovalWait != -time.Second {
		t.Fatalf("re-export lost wait: %v", pv3.ApprovalWait)
	}

	// 门槛为正时，零/负等待时长仍必须拒绝，错误可识别为 ErrBackupInvalid 且含策略编号。
	for _, wait := range []time.Duration{0, -time.Second} {
		b := decodeBackup(t, backup)
		p := b["policies"].([]interface{})[0].(map[string]interface{})
		p["approval_threshold"] = float64(10)
		p["approval_wait_nanos"] = float64(int64(wait))
		data := encodeBackup(t, b)
		wr, err := Restore(data)
		if !errors.Is(err, ErrBackupInvalid) {
			t.Fatalf("wait=%v: want ErrBackupInvalid, got %v", wait, err)
		}
		if wr != nil {
			t.Fatal("must not return partial wallet")
		}
		if !strings.Contains(err.Error(), `"pol"`) || !strings.Contains(err.Error(), "approval wait") {
			t.Fatalf("error should name policy and wait setting: %v", err)
		}
	}

	// 关闭审批但最长预留时长为负仍须拒绝。
	b := decodeBackup(t, backup)
	p := b["policies"].([]interface{})[0].(map[string]interface{})
	p["max_reserve_duration_nanos"] = float64(int64(-time.Second))
	if _, err := Restore(encodeBackup(t, b)); !errors.Is(err, ErrBackupInvalid) {
		t.Fatalf("negative max reserve duration: want ErrBackupInvalid, got %v", err)
	}
}

